//! Real public-network acceptance, with fixture-host consent (not desktop GUI consent).
use std::{fs,path::{Path,PathBuf},io::Read,num::NonZeroUsize,sync::Mutex,time::Duration};
use lu_core::{ansf::AnsfStore,ansf_live_chat::{LiveEvent,LiveKind},conversation_authority::TrustedUserTurnVerifier,inference_host::Cancellation,agent_tool_loop::ToolDispatchCheckpoint as Checkpoint,model_web_research_turn::ApprovedWebTurn,model_turn_journal::{ModelAuditKind as K,ModelTurnJournal},inference_supervisor::TrustedInferenceSupervisor,model_admission::ModelAdmissionManager,persistent_llama_backend::{PersistentEngineConfig,PersistentLlamaBackend},supervised_tool_generation::SupervisorModelStep};
use serde_json::Value;use sha2::{Digest,Sha256};
const CHAT:&str="c-web-research-0000000001";const TURN:&str="g-00000000000000000000000000000001";
struct Original{book:AnsfStore,request:&'static str}
impl TrustedUserTurnVerifier for Original{fn verify_user_turn(&self,c:&str,t:&str)->bool{c==CHAT&&t==TURN&&self.book.authenticated_chat_turn(c,t).ok().flatten().is_some_and(|v|v.0==self.request)&&self.book.latest_authenticated_chat_turn(c).ok().flatten().is_some_and(|v|v.0==t&&v.1==self.request)}}
fn hash(p:&Path)->String{let mut h=Sha256::new();let mut f=fs::File::open(p).unwrap();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn pinned(name:&str)->(PathBuf,String){let p=PathBuf::from(std::env::var(name).unwrap());let sha=std::env::var(format!("{name}_SHA256")).unwrap();assert!(p.is_absolute());assert_eq!(hash(&p),sha);(p,sha)}
async fn public_turns(expect_live:bool){
 let (exe,esha)=pinned("LU_CP06ER3_SERVER");let(gguf,_)=pinned("LU_CP06ER3_GGUF");let(curl,_)=pinned("LU_CP06ER3_CURL");let pin:[u8;32]=(0..esha.len()).step_by(2).map(|i|u8::from_str_radix(&esha[i..i+2],16).unwrap()).collect::<Vec<_>>().try_into().unwrap();
 let auth=format!("{:064x}",std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos());let mut manager=ModelAdmissionManager::new();let admitted=manager.admit(gguf.parent().unwrap(),gguf.file_name().unwrap().to_str().unwrap()).unwrap().clone();let supervisor=TrustedInferenceSupervisor::new("llama-cpu".into(),8192,vec![("model-1".into(),admitted)],move||PersistentLlamaBackend::new(PersistentEngineConfig{executable:exe.clone(),expected_sha256:pin,threads:NonZeroUsize::new(3).unwrap(),context_tokens:8192,startup_timeout:Duration::from_secs(90),request_timeout:Duration::from_secs(90),api_key:auth.clone(),load_observer:None})).unwrap();let sid="cp06er3-public";supervisor.load("model-1",sid.into(),"web-load").unwrap();let base=PathBuf::from(std::env::var("LU_CP06ER3_EVIDENCE").unwrap());let mut outcomes=Vec::new();
 for (tag,request,name,code) in [("fetch","Fetch web page https://example.org/","lu_web_fetch","FETCH_DENIED"),("academic","Search academic literature for photosynthesis","lu_web_academic_search","SEARCH_UNAVAILABLE")]{
  let root=base.join(tag);fs::create_dir_all(&root).unwrap();let book=AnsfStore::open(&root.join("chat.sqlite")).unwrap();book.create_session(CHAT,"workspace","Public test").unwrap();book.start_chapter(CHAT,"Original").unwrap();book.append_host_chat_event(CHAT,&LiveEvent{event_id:"e-00000000000000000000000000000001".into(),kind:LiveKind::User,text:request.into(),user_turn_id:Some(TURN.into()),legacy_turn_id:None,generation_id:None,call_id:None,tool_id:None}).unwrap();let original=Original{book,request};let audit_path=root.join("audit.sqlite");let audit=ModelTurnJournal::open(&audit_path).unwrap();let mut turn=ApprovedWebTurn::new_after_review(&original,CHAT,TURN,request,&curl,Cancellation::default()).unwrap();let mut model=SupervisorModelStep::new(&supervisor,sid.into(),format!("public-{tag}")).unwrap();let observed=Mutex::new(Vec::new());let r=turn.run(&mut model,&original,&audit,&||Ok(()),&|p|observed.lock().unwrap().push(p)).await;
  let rows=audit.events_for(CHAT,TURN).unwrap();let feedback:Vec<Value>=rows.iter().filter(|e|e.kind==K::ToolFeedback).map(|e|serde_json::from_str(&e.payload).unwrap()).collect();let common=rows.iter().any(|e|e.kind==K::ParsedCandidate&&e.payload==name)&&rows.iter().all(|e|e.kind!=K::HostRouteSelected)&&feedback.len()==1&&*observed.lock().unwrap()==[Checkpoint::Entered,Checkpoint::Returned]&&ModelTurnJournal::open(&audit_path).unwrap().events_for(CHAT,TURN).unwrap()==rows;
  let response=feedback.first().map(|v|&v["response"]);let good=if expect_live{match (&r,response){(Ok(report),Some(v))=>{let res=&v["result"];report.tool_calls==1&&report.host_routed_calls==0&&v["ok"]==true&&res["source_is_untrusted"]==true&&if tag=="fetch"{res["http_status"]==200&&res["source_url"]=="https://example.org/"&&res["content"].as_str().is_some_and(|s|!s.is_empty())}else{res["page"]==1&&res["leads_verified"]==false&&res["leads"].as_array().is_some_and(|a|!a.is_empty())}},_=>false}}else{r.is_err()&&response.is_some_and(|v|v["ok"]==false&&v["error"]["code"]==code)&&rows.iter().all(|e|e.kind!=K::FinalAnswer&&e.kind!=K::EvidencePresentation)};
  let old=observed.lock().unwrap().len();let replay=turn.run(&mut model,&original,&audit,&||Ok(()),&|p|observed.lock().unwrap().push(p)).await.is_err()&&observed.lock().unwrap().len()==old;
  println!("CP06ER3 {tag} expected_live={expect_live} model_and_dispatch={common} expected_outcome={good} replay_refused={replay} outcome={:?} error_code={:?}",r.as_ref().err(),response.and_then(|v|v["error"]["code"].as_str()));outcomes.push(common&&good&&replay);
 }supervisor.unload(sid,"web-unload").unwrap();assert!(supervisor.status().unwrap().pid.is_none());assert_eq!(outcomes,vec![true,true]);
}
#[tokio::test]
#[ignore="requires pinned local model and real public HTTPS access; no simulated response"]
async fn cp06er3_genuine_public_web_live(){public_turns(true).await;}
#[tokio::test]
#[ignore="requires pinned local model and genuinely unavailable public providers; no simulated response"]
async fn cp06er3_genuine_provider_unavailable(){public_turns(false).await;}
